/**
 * The decrypt pass over an archive page, and the notice a changed device key puts into it
 * (ADR 0006 §6).
 *
 * Every key here is generated by `@curlew/omemo` and every JID is synthetic. The encrypted
 * entries are built by our own send path rather than from recorded blobs, so what the pass is
 * handed is what a real page carries.
 *
 * The property these cases exist for: a key that changed under a device id the person already
 * knows is never silent. It gets its own line in the conversation, ONCE, and that line does not
 * move the message that proved it.
 */

import { describe, expect, it } from '@gjsify/unit';

import { generateKeyPair, toBase64, type DeviceId, type OmemoStorage } from '@curlew/omemo';
import { SecretStore } from '@curlew/store';
import {
  NS,
  SecretStoreOmemoStorage,
  decryptEntries,
  encryptedChatMessage,
  omemoEncryptFor,
  type ArchivedEntry,
  type XmlElement,
} from '@curlew/xmpp';

import {
  LATER,
  START,
  fakeNetwork,
  join,
  joinWith,
  type FakeNetwork,
  type Participant,
} from './fake-pep.ts';

const ALICE = 'alice@example.org';
const BOB = 'bob@example.org';
const STAMP = LATER.getTime();

/**
 * The side that reads: `decryptEntries` wants a storage that also journals the plaintext, which
 * only the `SecretStore`-backed one does. In-memory, so nothing of this reaches a disk.
 */
async function joinReceiver(net: FakeNetwork, jid: string) {
  return joinWith(net, jid, new SecretStoreOmemoStorage(SecretStore.open(':memory:')));
}

/** One archived `<message>` from `from`, carrying what `omemoEncryptFor` produced. */
async function archived(
  from: Participant,
  to: string,
  text: string,
  archiveId: string,
): Promise<ArchivedEntry> {
  const encrypted = await omemoEncryptFor(from.pep, from.storage, from.device, from.jid, to, text, {
    now: () => LATER,
  });
  if (encrypted === null) throw new Error('the send was answered with plaintext');
  const message = encryptedChatMessage({ to, id: archiveId, encrypted, fallback: 'encrypted' });
  return {
    archiveId,
    stampMs: STAMP,
    from: `${from.jid}/laptop`,
    to,
    type: 'chat',
    id: archiveId,
    originId: archiveId,
    body: 'encrypted',
    replaceId: null,
    retract: null,
    tombstone: false,
    attachmentUrls: [],
    replyToId: null,
    encrypted: true,
    omemo: {
      version: 'legacy',
      element: message.getChild('encrypted', NS.omemoLegacy) as unknown as XmlElement,
    },
    occupantJid: null,
  };
}

/** Put a key we never saw under the sender's device id, as a swap at the server would. */
async function pretendKeyChanged(storage: OmemoStorage, jid: string, deviceId: DeviceId) {
  await storage.saveIdentity(
    { jid, deviceId },
    { publicKey: toBase64(generateKeyPair().publicKey), trust: 'blind', firstSeen: START.toISOString() },
  );
}

export default async function omemoArchive(): Promise<void> {
  await describe('decrypting an archive page', async () => {
    await it('reads a message and leaves an unencrypted one alone', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const bob = await joinReceiver(net, BOB);
      const plain: ArchivedEntry = {
        ...(await archived(alice, BOB, 'ignored', 'a-0')),
        archiveId: 'a-0',
        body: 'in the clear',
        encrypted: false,
        omemo: null,
      };
      const entry = await archived(alice, BOB, 'the roof is leaking', 'a-1');

      const out = await decryptEntries(bob.storage, bob.device, BOB, [plain, entry], {
        now: () => LATER,
      });
      expect(out.length).toBe(2);
      expect(out[0].body).toBe('in the clear');
      expect(out[1].body).toBe('the roof is leaking');
      expect(out[1].encrypted).toBe(false);
      expect(out[1].notice).toBeUndefined();
    });

    await it('puts a notice before a message from a device whose key changed', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const bob = await joinReceiver(net, BOB);
      await pretendKeyChanged(bob.storage, ALICE, alice.device.deviceId);
      const entry = await archived(alice, BOB, 'this morning', 'a-2');

      const out = await decryptEntries(bob.storage, bob.device, BOB, [entry], { now: () => LATER });
      expect(out.length).toBe(2);

      const notice = out[0];
      expect(notice.notice).toBe(true);
      expect(notice.archiveId).toBe(`identity:${String(alice.device.deviceId)}:a-2`);
      // One millisecond earlier, so `assignSeqs` leaves the carrying message where it was.
      expect(notice.stampMs).toBe(STAMP - 1);
      expect(notice.encrypted).toBe(false);
      expect(notice.omemo).toBe(null);
      // Nothing of the carrier's identity: a notice is the target of no reply and no correction.
      expect(notice.id).toBe(null);
      expect(notice.originId).toBe(null);
      // The new fingerprint, grouped, and no base64 of the raw key anywhere in the line.
      expect((notice.body ?? '').includes(ALICE)).toBe(true);
      expect(/[0-9a-f]{8}/.test(notice.body ?? '')).toBe(true);

      expect(out[1].archiveId).toBe('a-2');
      expect(out[1].body).toBe('this morning');
      expect(out[1].stampMs).toBe(STAMP);
    });

    await it('writes the notice once, however often the page is fetched again', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const bob = await joinReceiver(net, BOB);
      await pretendKeyChanged(bob.storage, ALICE, alice.device.deviceId);
      const entry = await archived(alice, BOB, 'since when?', 'a-3');

      const first = await decryptEntries(bob.storage, bob.device, BOB, [entry], { now: () => LATER });
      expect(first.length).toBe(2);

      // The second pass is answered from the plaintext journal, before anything can notice an
      // identity again — the ratchet has already stepped and must not step twice.
      const again = await decryptEntries(bob.storage, bob.device, BOB, [entry], { now: () => LATER });
      expect(again.length).toBe(1);
      expect(again[0].body).toBe('since when?');
      expect(again[0].notice).toBeUndefined();
    });

    await it('says nothing about an identity it never held', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const bob = await joinReceiver(net, BOB);
      // A device Bob meets for the first time is trusted blindly (BTBV) and is no event.
      const out = await decryptEntries(
        bob.storage,
        bob.device,
        BOB,
        [await archived(alice, BOB, 'hello', 'a-4')],
        { now: () => LATER },
      );
      expect(out.length).toBe(1);
      expect(out[0].notice).toBeUndefined();
    });

    await it('decrypts nothing and notices nothing when only the journal may answer', async () => {
      const net = fakeNetwork();
      const alice = await join(net, ALICE);
      const bob = await joinReceiver(net, BOB);
      await pretendKeyChanged(bob.storage, ALICE, alice.device.deviceId);
      const entry = await archived(alice, BOB, 'the lookback', 'a-5');

      const out = await decryptEntries(bob.storage, bob.device, BOB, [entry], {
        now: () => LATER,
        journalOnly: true,
      });
      expect(out.length).toBe(1);
      expect(out[0].encrypted).toBe(true);
      expect(out[0].body).toBe('encrypted');
    });
  });
}
